const languageButtons=document.querySelectorAll("[data-language]");const translatable=document.querySelectorAll("[data-i18n]");const translatableAlt=document.querySelectorAll("[data-i18n-alt]");const form=document.querySelector(".reservation-form");const formStatus=document.querySelector(".form-status");const dateInput=document.querySelector("#booking-date");let activeLanguage="ru";
function applyLanguage(language){activeLanguage=language;const text=translations[language];document.documentElement.lang=language;document.title=text.title;document.querySelector('meta[name="description"]').content=text.description;translatable.forEach((element)=>{element.innerHTML=text[element.dataset.i18n]});translatableAlt.forEach((element)=>{element.alt=text[element.dataset.i18nAlt]});languageButtons.forEach((button)=>{const selected=button.dataset.language===language;button.classList.toggle("is-active",selected);button.setAttribute("aria-pressed",String(selected))});formStatus.textContent=""}
languageButtons.forEach((button)=>button.addEventListener("click",()=>applyLanguage(button.dataset.language)));

const fullMenuTrigger=document.querySelector(".full-menu__trigger");const fullMenuPanel=document.querySelector(".full-menu__panel");const fullMenuLabel=document.querySelector(".full-menu__label");function setFullMenuState(isOpen){fullMenuTrigger.setAttribute("aria-expanded",String(isOpen));fullMenuPanel.classList.toggle("is-open",isOpen);fullMenuPanel.setAttribute("aria-hidden",String(!isOpen));fullMenuPanel.inert=!isOpen;fullMenuLabel.textContent=translations[activeLanguage][isOpen?"fullMenuClose":"fullMenuOpen"]}fullMenuPanel.inert=true;fullMenuTrigger.addEventListener("click",()=>setFullMenuState(fullMenuTrigger.getAttribute("aria-expanded")!=="true"));languageButtons.forEach((button)=>button.addEventListener("click",()=>setFullMenuState(fullMenuTrigger.getAttribute("aria-expanded")==="true")));

const menuSection=document.querySelector("#menu");document.querySelectorAll('a[href="#menu"]').forEach((link)=>link.addEventListener("click",(event)=>{event.preventDefault();window.scrollTo({top:menuSection.offsetTop,behavior:"smooth"});history.replaceState(null,"","#menu")}));

const menuButton=document.querySelector(".menu-toggle");const navigation=document.querySelector(".site-nav");function closeMenu(){navigation.classList.remove("is-open");menuButton.setAttribute("aria-expanded","false");document.body.classList.remove("menu-open")}menuButton.addEventListener("click",()=>{const isOpen=menuButton.getAttribute("aria-expanded")==="true";if(isOpen)closeMenu();else{navigation.classList.add("is-open");menuButton.setAttribute("aria-expanded","true");document.body.classList.add("menu-open")}});navigation.querySelectorAll("a").forEach((link)=>link.addEventListener("click",closeMenu));document.addEventListener("keydown",(event)=>{if(event.key==="Escape")closeMenu()});

const revealItems=document.querySelectorAll(".reveal");if("IntersectionObserver" in window){const observer=new IntersectionObserver((entries,revealObserver)=>{entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add("is-visible");revealObserver.unobserve(entry.target)}})},{threshold:.12});revealItems.forEach((item)=>observer.observe(item))}else revealItems.forEach((item)=>item.classList.add("is-visible"));
dateInput.min=new Date().toISOString().split("T")[0];form.addEventListener("submit",(event)=>{event.preventDefault();const phone=form.elements.phone;const phoneIsValid=/^[+\d][\d\s()\-]{6,}$/.test(phone.value.trim());form.querySelectorAll("input, select").forEach((field)=>field.classList.remove("is-invalid"));if(!form.checkValidity()||!phoneIsValid){form.querySelectorAll("input, select").forEach((field)=>{if(!field.validity.valid||(field===phone&&!phoneIsValid))field.classList.add("is-invalid")});formStatus.textContent=phone.value&&!phoneIsValid?translations[activeLanguage].invalidPhone:translations[activeLanguage].invalidForm;return}formStatus.textContent=translations[activeLanguage].success;form.reset();dateInput.min=new Date().toISOString().split("T")[0]});document.querySelector("#current-year").textContent=new Date().getFullYear();
